import SwiftUI

// MARK: - SwiftUI 动画系统三件套：属性动画 / 显式动画 / 过渡动画
struct AnimationShowcaseView: View {
    @State private var isExpanded = false
    @State private var isLiked = false

    // 统一动画曲线：全局复用，保证产品手感一致
    private var appSpring: Animation {
        .spring(response: 0.45, dampingFraction: 0.72)
    }

    var body: some View {
        VStack(spacing: 24) {

            // 1) 隐式动画：只在 isExpanded 变化时，对该视图生效
            RoundedRectangle(cornerRadius: isExpanded ? 24 : 8)
                .fill(isExpanded ? Color.orange : Color.blue)
                .frame(width: isExpanded ? 280 : 140,
                       height: isExpanded ? 180 : 90)
                .animation(appSpring, value: isExpanded)

            // 2) 过渡动画：视图「插入 / 移除」时的表现，需配合 withAnimation
            if isExpanded {
                Text("详细信息已展开")
                    .font(.headline)
                    .padding(10)
                    .background(.thinMaterial, in: Capsule())
                    .transition(.scale.combined(with: .opacity))
            }

            // 3) 显式动画：把状态变更包进 withAnimation，作用域覆盖整棵子树
            Button {
                withAnimation(appSpring) {
                    isExpanded.toggle()
                }
            } label: {
                Label(isExpanded ? "收起" : "展开",
                      systemImage: isExpanded ? "chevron.up" : "chevron.down")
                    .padding(.horizontal, 18)
                    .padding(.vertical, 10)
            }
            .buttonStyle(.borderedProminent)

            // 4) 状态 + 缩放联动：典型点赞反馈
            Button {
                withAnimation(.bouncy(extraBounce: 0.15)) { isLiked.toggle() }
            } label: {
                Image(systemName: isLiked ? "heart.fill" : "heart")
                    .font(.system(size: 42))
                    .foregroundStyle(isLiked ? Color.red : Color.secondary)
                    .scaleEffect(isLiked ? 1.25 : 1.0)
            }
            .buttonStyle(.plain)
        }
        .padding(32)
    }
}

#Preview {
